"""Thread-safe LRU cache with optional per-entry TTL (seconds)."""
import threading
import time
from collections import OrderedDict


class LRUCache:
    def __init__(self, capacity):
        if capacity <= 0:
            raise ValueError("capacity must be positive")
        self._capacity = capacity
        self._data = {}          # key -> (value, expires_at | None)
        self._order = OrderedDict()  # keys in recency order (oldest first)
        self._lock = threading.Lock()
        self._hits = 0
        self._misses = 0
        self._evictions = 0

    def _is_expired(self, expires_at):
        return expires_at is not None and time.monotonic() >= expires_at

    def get(self, key, default=None):
        with self._lock:
            entry = self._data.get(key)
            if entry is None or self._is_expired(entry[1]):
                self._misses += 1
                if entry is not None:  # lazily drop expired entry
                    del self._data[key]
                    self._order.pop(key, None)
                    self._evictions += 1
                return default
            value, _ = entry
            self._hits += 1
            self._order.move_to_end(key)
            return value

    def put(self, key, val, ttl_seconds=None):
        with self._lock:
            expires_at = None if ttl_seconds is None else time.monotonic() + ttl_seconds
            self._data[key] = (val, expires_at)
            if key in self._order:
                self._order.move_to_end(key)
            else:
                self._order.append(key)
            while len(self._order) > self._capacity:
                old_key, _ = self._order.popitem(last=False)  # oldest first
                del self._data[old_key]
                self._evictions += 1

    def evict_expired(self):
        now = time.monotonic()
        with self._lock:
            expired = [k for k, (_, exp) in self._data.items()
                       if exp is not None and now >= exp]
            for key in expired:
                del self._data[key]
                self._order.pop(key, None)
                self._evictions += 1
        return len(expired)

    def stats(self):
        with self._lock:
            return {"hits": self._hits, "misses": self._misses,
                    "evictions": self._evictions}

    def __len__(self):
        with self._lock:
            return len(self._data)

