"""Thread-safe LRU cache with optional per-key TTLs."""

import threading
from collections import OrderedDict


class LRUCache:
    def __init__(self, capacity):
        if capacity < 1:
            raise ValueError("capacity must be >= 1")
        self._capacity = capacity
        self._data = {}              # key -> (value, expires_at | None)
        self._order = []             # keys, least-recently-used first
        self._pos = {}               # key -> index in _order
        self._hits = 0
        self._misses = 0
        self._evictions = 0
        self._lock = threading.Lock()

    def get(self, key, default=None):
        with self._lock:
            entry = self._data.get(key)
            if entry is None or self._expired(entry[1]):
                if entry is not None and self._expired(entry[1]):
                    self._remove(key)   # lazy expiry counts as eviction
                self._misses += 1
                return default
            self._hits += 1
            self._touch(key)
            return entry[0]

    def put(self, key, val, ttl_seconds=None):
        with self._lock:
            expires = None if ttl_seconds is None else _now() + ttl_seconds
            if key in self._data:
                self._remove(key)
            elif len(self._data) >= self._capacity:
                oldest = self._order.pop(0)          # LRU eviction
                del self._pos[oldest]
                del self._data[oldest]
                self._evictions += 1
            self._data[key] = (val, expires)
            self._pos[key] = len(self._order)
            self._order.append(key)

    def evict_expired(self):
        """Remove all expired entries; returns count removed."""
        with self._lock:
            now = _now()
            dead = [k for k, (_, exp) in self._data.items() if exp is not None and now >= exp]
            for key in dead:
                self._remove(key)
            return len(dead)

    def stats(self):
        with self._lock:
            return {"hits": self._hits, "misses": self._misses, "evictions": self._evictions}

    def __len__(self):
        with self._lock:
            return len(self._data)

    # --- internals (call only while holding _lock) ---
    @staticmethod
    def _expired(expires_at):
        return expires_at is not None and _now() >= expires_at

    def _touch(self, key):
        i = self._pos.pop(key)
        del self._order[i]
        self._pos[key] = len(self._order)
        self._order.append(key)

    def _remove(self, key):
        self._data.pop(key)
        i = self._pos.pop(key)
        del self._order[i]


def _now():
    import time
    return time.monotonic()

