import threading, time
from lru_cache import LRUCache

# LRU eviction order + stats
c = LRUCache(2)
assert c.get("a") is None and c.stats() == {"hits": 0, "misses": 1, "evictions": 0}
c.put("a", 1); c.put("b", 2); c.get("a")   # a hot, b cold
c.put("c", 3)                               # evicts b
assert c.get("b") is None and c.get("a") == 1 and c.get("c") == 3
s = c.stats(); assert (s["hits"], s["misses"], s["evictions"]) == (2, 1, 1), s

# default on miss; overwrite existing key keeps capacity semantics
d = LRUCache(1); d.put("x", 1)
assert d.get("x", "fallback") == 1 and d.get("y", "fb") == "fb"
d.put("x", 9); assert len(d) == 1 and d.get("x") == 9

# TTL: expired entries behave as misses; evict_expired returns count
t = LRUCache(4)
t.put("live", 1, ttl_seconds=60)
t.put("dead", 2, ttl_seconds=0.05)
time.sleep(0.06)
assert t.get("dead") is None and t.evict_expired() == 1
assert t.stats()["evictions"] == 1 and len(t) == 1
# fresh TTL still valid
t.put("fresh", 3, ttl_seconds=60); assert t.get("fresh") == 3

# thread safety: mixed readers/writers + expiry under contention
p = LRUCache(50)
errs = []
def writer():
    try:
        for i in range(2000):
            p.put(i % 100, i, ttl_seconds=None)
    except Exception as e: errs.append(e)
def reader():
    try:
        for _ in range(2000):
            p.get(7); p.stats()
    except Exception as e: errs.append(e)
def exirer():
    try:
        for _ in range(100):
            p.evict_expired()
    except Exception as e: errs.append(e)
ths = [threading.Thread(target=w) for w in (writer,)*4 + (reader,)*4 + (exirer,)*2]
[x.start() for x in ths]; [x.join() for x in ths]
assert not errs and len(p) <= 50

print("OK", c.stats())
